import { _t } from "../../../utils/Translator";
import type { CaseItem } from "../case/Case";
import Document, { DocumentItem } from "../document/Document";
import { ComposeMainPages } from "../composemain/ComposeMain";
import React, { useEffect, useState } from "react";
import api from "../../api";
import { ContentType, HttpVerb, sendHttpRequest } from "../../../utils/httpRequest";
import Error from "../error/Error";
import Progress from "../progress/Progress";
import { TagItem } from "../tags/tag";

/* global Office */

interface InsertDocumentsPageProps {
  selectedCase: CaseItem;
  goToPage: (page: ComposeMainPages) => void;
  getConnectionToken: () => string;
  documentTags?: TagItem[];
}

const InsertDocumentsPage: React.FC<InsertDocumentsPageProps> = ({
  selectedCase,
  goToPage,
  getConnectionToken,
}) => {
  const [documents, setDocuments] = useState<DocumentItem[]>([]);
  const [selectedDocuments, setSelectedDocuments] = useState<DocumentItem[]>([]);
  const [error, setError] = useState<string>("");
  const [processing, setProcessing] = useState<boolean>(false);

  useEffect(() => {
    setError("");
    setSelectedDocuments([]);
    setDocuments([]);
    setProcessing(false);

    const cid = selectedCase?.id;
    if (!cid) return;

    const token = getConnectionToken();
    setProcessing(true);

    const documentsPromise = sendHttpRequest(
      HttpVerb.POST,
      api.baseURL + api.getCaseDocuments, // /outlook/get_case_documents
      ContentType.Json,
      token,
      { case_id: cid },
      true
    ).promise;

    documentsPromise
      .then((dResStr) => {
        const dRes = JSON.parse(dResStr);
        if (!dRes.result?.success) {
          setError(String(dRes.result?.error || "Failed to load documents"));
          setDocuments([]);
        } else {
          setDocuments(dRes.result.data?.documents || []);
        }
      })
      .catch((e) => {
        setError(String(e));
        setDocuments([]);
      })
      .finally(() => setProcessing(false));
  }, [selectedCase?.id, getConnectionToken]);

  const getDocumentData = async (document: DocumentItem, getPdf: boolean) => {
    let response = null;
    try {
      const request = sendHttpRequest(
        HttpVerb.POST,
        api.baseURL + api.getDocumentData,
        ContentType.Json,
        getConnectionToken(),
        { document_id: document.id, get_pdf: getPdf ? 1 : 0 },
        true
      );
      response = JSON.parse(await request.promise);
    } catch (e) {
      setError(String(e));
    }
    return response;
  };

  const getResponseRoot = (response: any) => response?.result ?? response;

  const addDocument = async (document: DocumentItem, getPdf: boolean) => {
    const response = await getDocumentData(document, getPdf);
    const root = getResponseRoot(response);
    if (!root?.success) {
      setError(String(root?.error || "Failed to load document data"));
      return;
    }
    if (!root?.data?.datas) {
      setError(
        getPdf
          ? `No PDF available for ${document.name || "document"}`
          : `No file data available for ${document.name || "document"}`
      );
      return;
    }
    Office.context.mailbox.item.addFileAttachmentFromBase64Async(
      root.data.datas,
      root.data.filename
    );
  };

  const addSelectedDocuments = async (getPdf: boolean) => {
    const docs = selectedDocuments;
    if (docs.length === 0) return;
    for (const doc of docs) {
      await addDocument(doc, getPdf);
    }
    goToPage(ComposeMainPages.ComposeMainPage);
  };

  const getAddDocumentButton = () => (
    <button
      title="Add original"
      type="button"
      className="btn btn-primary"
      onMouseDown={(e) => e.preventDefault()}
      onClick={() => addSelectedDocuments(false)}
    >
      {_t("Original")}
    </button>
  );

  const getAddDocumentAsPdfButton = () => (
    <button
      title="Add PDF"
      type="button"
      className="btn btn-primary ms-2"
      onMouseDown={(e) => e.preventDefault()}
      onClick={() => addSelectedDocuments(true)}
    >
      {_t("PDF")}
    </button>
  );

  const getDocumentButtons = () => {
    if (selectedDocuments.length === 0) return null;
    return (
      <>
        {getAddDocumentButton()}
        {getAddDocumentAsPdfButton()}
      </>
    );
  };

  return (
    <div>
      <div className="d-flex align-items-center gap-2 page-header">
        <button
          title="Return"
          type="button"
          className="btn btn-default"
          onClick={() => goToPage(ComposeMainPages.OpenCasePage)}
        >
          <i className="fa fa-arrow-left text-primary" aria-hidden="true"></i>
        </button>
        <span className="page-title">{_t("Select documents")}</span>
      </div>

      <Error error={error} setError={setError} />

      <>
        <Document
          documents={documents}
          selectedDocuments={selectedDocuments}
          onSelectedDocumentsChange={setSelectedDocuments}
        />
        <div className="d-flex justify-content-end page-button-container">
          {getDocumentButtons()}
        </div>
      </>

      <Progress processing={processing} />
    </div>
  );
};

export default InsertDocumentsPage;
