import React, { useState, useEffect, useContext } from "react";
import { ContentType, HttpVerb, sendHttpRequest } from "../../../utils/httpRequest";
import api from "../../api";
import { CaseItem } from "../case/Case";
import ComposeMainPage from "../composepages/ComposeMainPage";
import { MailTemplateItem } from "../mail_template/MailTemplate";
import Footer from "../footer/Footer";
import Error from "../error/Error";
import Header, { UserData } from "../header/Header";
import { TagItem } from "../tags/tag";
import InsertDocumentsPage from "../composepages/InsertDocumentsPage";
import GenerateMailPage from "../composepages/GenerateMailPage";
import InsertPartiesPage from "../composepages/InsertPartiesPage";
import OpenAnalysisPage from "../composepages/OpenAnalysisPage";
import OpenWorkflowPage from "../composepages/OpenWorkflowPage";
import OpenPartiesPage from "../composepages/OpenPartiesPage";
import { AnalysisItem } from "../analysis/Analysis";
import { WorkflowItem } from "../workflow/Workflow";
import AnalysisPage from "../composepages/AnalysisPage";
import OpenCasePage from "../composepages/OpenCasePage";

const getConnectionToken = () => {
  return "Bearer " + localStorage.getItem("odooConnectionToken");
};

export enum ComposeMainPages {
  ComposeMainPage,
  OpenCasePage,
  InsertPartiesPage,
  OpenPartiesPage,
  InsertDocumentsPage,
  GenerateMailPage,
  OpenAnalysisPage,
  AnalysisPage,
  OpenWorkflowPage,
}

type ComposeMainProps = {
  disconnect: () => void;
};

const ComposeMain: React.FC<ComposeMainProps> = (props: ComposeMainProps) => {
  const { disconnect } = props;
  const [page, setPage] = useState<ComposeMainPages>(ComposeMainPages.ComposeMainPage);
  const [error, setError] = useState<string>("");
  const [selectedCase, setSelectedCase] = useState<CaseItem>(null);
  const [mailTemplates, setMailTemplates] = useState<MailTemplateItem[]>([]);
  const [selectedMailTemplate, setSelectedMailTemplate] = useState<MailTemplateItem>(null);
  const [userInfo, setUserInfo] = useState<UserData>(null);
  const [documentTags, setDocumentTags] = useState<TagItem[]>([]);
  const [partyTags, setPartyTags] = useState<TagItem[]>([]);
  const [selectedAnalysis, setSelectedAnalysis] = useState<AnalysisItem | null>(null);
  const [selectedWorkflow, setSelectedWorkflow] = useState<WorkflowItem | null>(null);
  const [workflows, setWorkflows] = useState<WorkflowItem[]>([]);
  const [openCaseReturnPage, setOpenCaseReturnPage] = useState<ComposeMainPages | null>(null);
  const [openCaseConfirmPage, setOpenCaseConfirmPage] = useState<ComposeMainPages | null>(null);
  const [selectedPartyIds, setSelectedPartyIds] = useState<number[]>([]);

  const getComposeData = async () => {
    let response = null;
    try {
      const url = api.baseURL + api.getComposeData;
      const token = getConnectionToken();
      const request = sendHttpRequest(
        HttpVerb.POST,
        url,
        ContentType.Json,
        token,
        {},
        true
      );
      const raw = await request.promise;
      response = JSON.parse(raw);
    } catch (error) {
      throw { error, baseURL: api.baseURL, url: api.baseURL + api.getComposeData, hasToken: !!localStorage.getItem("odooConnectionToken") };
    }
    return response; 
  };

  const getData = async () => {
    try {
      const response = await getComposeData();
      if (!response) {
        setError("Failed to load compose data.");
        return;
      }
      const root = response?.result ?? response;
      if (root?.success) {
        setMailTemplates(root.data?.mail_templates || []);
        setDocumentTags(root.data?.document_tags || []);
        setPartyTags(root.data?.party_tags || []);
        setWorkflows(root.data?.workflows || []);
        setUserInfo(root.data?.user_info || null);
      } else {
        const err = root?.error || "Failed to load compose data.";
        setError(JSON.stringify({ error: err, response }, null, 2));
      }
    } catch (error) {
      setError(JSON.stringify(error, null, 2));
    }
  }

  const loadData = () => {
    getData();
    setPage(ComposeMainPages.ComposeMainPage);
  };
 
  useEffect(() => {
    loadData();
  }, []);

  const goToOpenCase = (
    confirmPage: ComposeMainPages,
    returnPage: ComposeMainPages = ComposeMainPages.ComposeMainPage
  ) => {
    setOpenCaseConfirmPage(confirmPage);
    setOpenCaseReturnPage(returnPage);
    setPage(ComposeMainPages.OpenCasePage);
  };

  let composeMainPage = (
    <ComposeMainPage 
      goToPage={setPage} 
      onOpenCase={goToOpenCase}
    />
  );

  let generateMailPage = (
    <GenerateMailPage 
      mailTemplates={mailTemplates}
      selectedMailTemplate={selectedMailTemplate}
      onMailTemplateSelected={setSelectedMailTemplate}
      selectedCase={selectedCase}
      selectedPartyIds={selectedPartyIds}
      getConnectionToken={getConnectionToken} 
      goToPage={setPage}
    />
  );

  let insertDocumentsPage = (
    <InsertDocumentsPage 
      selectedCase={selectedCase}
      goToPage={setPage}
      getConnectionToken={getConnectionToken}
      documentTags={documentTags}
    />
  );

  let openPartiesPage = (
    <OpenPartiesPage
      selectedCase={selectedCase}
      getConnectionToken={getConnectionToken}
      goToPage={setPage}
      partyTags={partyTags}
      onSelectedPartyIdsChange={setSelectedPartyIds}
    />
  );
  let insertPartiesPage = (
    <InsertPartiesPage
      selectedCase={selectedCase}
      getConnectionToken={getConnectionToken}
      goToPage={setPage}
      goToOpenCasePage={() =>
        goToOpenCase(ComposeMainPages.InsertPartiesPage, ComposeMainPages.ComposeMainPage)
      }
      partyTags={partyTags}
      onSelectedPartyIdsChange={setSelectedPartyIds}
    />
  );

  let openAnalysisPage = (
    <OpenAnalysisPage 
      selectedCase={selectedCase}
      selectedAnalysis={selectedAnalysis}
      onCaseSelected={setSelectedCase}
      onAnalysisSelected={setSelectedAnalysis}
      workflows={workflows}
      goToPage={setPage}
    />
  );

  let analysisPage = (
    <AnalysisPage
      getConnectionToken={getConnectionToken}
      selectedAnalysis={selectedAnalysis}
      onAnalysisSelected={setSelectedAnalysis}
      selectedCase={selectedCase}
      onCaseSelected={setSelectedCase}
      selectedWorkflow={selectedWorkflow}
      onWorkflowSelected={setSelectedWorkflow}
      goToPage={setPage}
      goToOpenCasePage={() => goToOpenCase(ComposeMainPages.AnalysisPage, ComposeMainPages.AnalysisPage)}
    />
  );

  let openWorkflowPage = (
    <OpenWorkflowPage
      workflows={workflows}
      selectedWorkflow={selectedWorkflow}
      onWorkflowSelected={setSelectedWorkflow}
      returnPage={ComposeMainPages.AnalysisPage}
      onConfirm={() => setPage(ComposeMainPages.AnalysisPage)}
      goToPage={setPage}
    />
  );

  let openCasePage = (
    <OpenCasePage
      selectedCase={selectedCase}
      onCaseSelected={setSelectedCase}
      onConfirm={() => setPage(openCaseConfirmPage ?? ComposeMainPages.ComposeMainPage)}
      returnPage={openCaseReturnPage ?? ComposeMainPages.ComposeMainPage}
      goToPage={setPage}
    />
  );

  let wrapPage = (page) => (
    <>
      <Header userData={userInfo} />
      <div className="page">
        <Error error={error} setError={setError} />
        {page}
      </div>
      <Footer disconnect={disconnect} />
    </>
  );

  switch (page) {
    case ComposeMainPages.ComposeMainPage:
      return wrapPage(composeMainPage);
    case ComposeMainPages.GenerateMailPage:
      return wrapPage(generateMailPage);
    case ComposeMainPages.InsertPartiesPage:
      return wrapPage(insertPartiesPage);
    case ComposeMainPages.OpenCasePage:
      return wrapPage(openCasePage);
    case ComposeMainPages.OpenPartiesPage:
      return wrapPage(openPartiesPage);
    case ComposeMainPages.InsertDocumentsPage:
      return wrapPage(insertDocumentsPage);
    case ComposeMainPages.OpenAnalysisPage:
      return wrapPage(openAnalysisPage);
    case ComposeMainPages.AnalysisPage:
      return wrapPage(analysisPage);
    case ComposeMainPages.OpenWorkflowPage:
      return wrapPage(openWorkflowPage);
    default:
      return composeMainPage;
  }

};

export default ComposeMain;
