import * as React from "react";
import { useEffect, useState } from "react";
import { _t } from "../../../utils/Translator";
import type { CaseItem } from "../case/Case";
import Party, { PartyItem } from "../party/Party";
import { sendHttpRequest, HttpVerb, ContentType } from "../../../utils/httpRequest";
import api from "../../api";
import { ComposeMainPages } from "../composemain/ComposeMain";
import Error from "../error/Error";
import Progress from "../progress/Progress";
import { TagItem } from "../tags/tag";

/* global Office */

interface InsertPartiesPageProps {
  selectedCase: CaseItem | null;
  getConnectionToken: () => string;
  goToPage: (page: ComposeMainPages) => void;
  goToOpenCasePage: () => void;
  partyTags?: TagItem[];
  onSelectedPartyIdsChange: (ids: number[]) => void;
}

const InsertPartiesPage: React.FC<InsertPartiesPageProps> = ({
  selectedCase,
  getConnectionToken,
  goToPage,
  goToOpenCasePage,
  onSelectedPartyIdsChange,
}) => {
  const [parties, setParties] = useState<PartyItem[]>([]);
  const [selectedParties, setSelectedParties] = useState<PartyItem[]>([]);
  const [error, setError] = useState<string>("");
  const [processing, setProcessing] = useState<boolean>(false);

  useEffect(() => {
    setError("");
    setSelectedParties([]);
    setParties([]);
    onSelectedPartyIdsChange([]);

    const caseId = selectedCase?.id;
    if (!caseId) return;

    const req = sendHttpRequest(
      HttpVerb.POST,
      api.baseURL + api.getCaseParties,
      ContentType.Json,
      getConnectionToken(),
      { case_id: caseId },
      true
    );

    req.promise
      .then((resStr) => {
        const res = JSON.parse(resStr);
        if (!res.result?.success) {
          setError(String(res.result?.error || "Failed to load parties"));
          return;
        }
        setParties(res.result.data?.parties || []);
      })
      .catch((e) => setError(String(e)));
  }, [selectedCase?.id, getConnectionToken]);

  useEffect(() => {
    onSelectedPartyIdsChange(selectedParties.map((p) => p.id));
  }, [selectedParties, onSelectedPartyIdsChange]);

  const buildRecipients = () =>
    selectedParties
      .map((p) => (p.email || "").trim())
      .filter((email) => email.length > 0);

  const addRecipients = (field: "to" | "cc" | "bcc") => {
    const emails = buildRecipients();
    if (emails.length === 0) {
      setError("No email addresses found for selected parties.");
      return;
    }

    const item = Office.context.mailbox.item;
    const addAsync =
      field === "to"
        ? item.to.addAsync
        : field === "cc"
        ? item.cc.addAsync
        : item.bcc.addAsync;

    addAsync.call(item, emails, (result: Office.AsyncResult<void>) => {
      if (result.status === Office.AsyncResultStatus.Failed) {
        setError(result.error?.message || "Failed to add recipients.");
        return;
      }
      goToPage(ComposeMainPages.ComposeMainPage);
    });
  };

  return (
    <div>
      <div className="d-flex align-items-center gap-2 page-header">
        <button
          title="Return"
          type="button"
          className="btn btn-default"
          onClick={goToOpenCasePage}
        >
          <i className="fa fa-arrow-left text-primary" aria-hidden="true"></i>
        </button>
        <span className="page-title">{_t("Select parties")}</span>
      </div>

      <Error error={error} setError={setError} />

      <Party
        parties={parties}
        selectedParties={selectedParties}
        onSelectedPartiesChange={setSelectedParties}
      />

      <div className="d-flex justify-content-end page-button-container">
        {selectedParties.length > 0 && (
          <>
            <button
              title="Add TO"
              type="button"
              className="btn btn-primary"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => addRecipients("to")}
            >
              {_t("TO")}
            </button>
            <button
              title="Add CC"
              type="button"
              className="btn btn-primary ms-2"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => addRecipients("cc")}
            >
              {_t("CC")}
            </button>
            <button
              title="Add BCC"
              type="button"
              className="btn btn-primary ms-2"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => addRecipients("bcc")}
            >
              {_t("BCC")}
            </button>
          </>
        )}
      </div>

      <Progress processing={processing} />
    </div>
  );
};

export default InsertPartiesPage;
