import React, { useCallback } from "react";
import { _t } from "../../../utils/Translator";
import SearchTagMultiSelect from "../searchselect/SearchTagMultiSelect";
import type { SearchTagItem } from "../searchselect/SearchTagMultiSelect";
import { TagItem } from "../tags/tag";

export interface PartyItem {
  id: number;
  caseId: number;
  name: string;
  reference: string;
  salutation: string;
  email: string;
  tags: TagItem[];
}

interface PartyProps {
  parties: PartyItem[];
  selectedParties: PartyItem[];
  onSelectedPartiesChange: (items: PartyItem[]) => void;
}

const normalize = (s: string) => (s || "").trim().replace(/\s+/g, " ");
const makeKey = (p: PartyItem) =>
  `${normalize(p.name).toLowerCase()}||${normalize(p.reference).toLowerCase()}`;

const Party: React.FC<PartyProps> = ({
  parties,
  selectedParties,
  onSelectedPartiesChange,
}) => {
  const handleSelectionChange = useCallback(
    (items: SearchTagItem[]) => {
      const unique = [] as PartyItem[];
      for (const item of items) {
        const party = item as PartyItem;
        const key = makeKey(party);
        if (!unique.some((sp) => makeKey(sp) === key)) {
          unique.push(party);
        }
      }
      onSelectedPartiesChange(unique);
    },
    [onSelectedPartiesChange]
  );

  return (
    <div>
      <SearchTagMultiSelect
        items={parties as unknown as SearchTagItem[]}
        selectedItems={selectedParties as unknown as SearchTagItem[]}
        onSelectionChange={handleSelectionChange}
        selectText={_t("Select party")}
        searchText={_t("Search party")}
      />
    </div>
  );
};

export default Party;
