import React from "react";
import { _t } from "../../../utils/Translator";
import { TagItem } from "../tags/tag";
import SearchTagMultiSelect from "../searchselect/SearchTagMultiSelect";
import type { SearchTagItem } from "../searchselect/SearchTagMultiSelect";

export interface DocumentItem {
    name: string;
    filename: string;
    id: number;
    caseId: number;
    tags: TagItem[];
    hasPdf: boolean;
}

interface DocumentProps {
    documents: DocumentItem[];
    selectedDocuments: DocumentItem[];
    onSelectedDocumentsChange: (docs: DocumentItem[]) => void;
}

const Document: React.FC<DocumentProps> = ({
    documents,
    selectedDocuments,
    onSelectedDocumentsChange,
}) => {
    return (
        <div>
        <SearchTagMultiSelect
        items={documents as unknown as SearchTagItem[]}
        selectedItems={selectedDocuments as unknown as SearchTagItem[]}
        onSelectionChange={(items) =>
            onSelectedDocumentsChange(items as unknown as DocumentItem[])
        }
        selectText={_t("Select document")}
        searchText={_t("Search document")}
      />
    </div>
  );
};

export default Document;
