import * as React from "react";
import { TagItem } from "../tags/tag";
import type { SearchItem } from "./SearchSelect";

export interface SearchTagItem extends SearchItem {
  tags: TagItem[];
}

export interface SearchTagMultiSelectProps {
  items: SearchTagItem[];
  selectedItems: SearchTagItem[];
  onSelectionChange: (items: SearchTagItem[]) => void;
  selectText: string;
  searchText: string;
}

export interface SearchTagMultiSelectState {
  searchInput: string;
  isFocused: boolean;
}

export default class SearchTagMultiSelect extends React.Component<
  SearchTagMultiSelectProps,
  SearchTagMultiSelectState
> {
  private inputRef = React.createRef<HTMLTextAreaElement>();
  private static normalizeSearch = (value: string) =>
    value.trim().toLowerCase();

  constructor(props: SearchTagMultiSelectProps) {
    super(props);
    this.state = {
      searchInput: "",
      isFocused: false,
    };
  }

  componentDidUpdate(prevProps: SearchTagMultiSelectProps) {
    if (prevProps.selectedItems !== this.props.selectedItems) {
      // Keep input text; no sync needed for multiselect.
      this.autoResize();
    }
  }

  autoResize = () => {
    const el = this.inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  };

  setSearchInput = (value: string, isFocused = true) => {
    this.setState({ searchInput: value, isFocused }, this.autoResize);
  };

  filterItem = (item: SearchTagItem, searchInput: string) => {
    if (item.name.toLowerCase().includes(searchInput)) {
      return true;
    }
    return item.tags.some((tag) =>
      tag.name.toLowerCase().includes(searchInput)
    );
  };

  getFilteredItems = () => {
    const searchInputLower = SearchTagMultiSelect.normalizeSearch(
      this.state.searchInput
    );
    const sourceItems = Array.isArray(this.props.items) ? this.props.items : [];
    return searchInputLower
      ? sourceItems.filter((item) => this.filterItem(item, searchInputLower))
      : sourceItems;
  };

  isSelected = (item: SearchTagItem) => {
    return this.props.selectedItems.some((s) => s.id === item.id);
  };

  toggleSelected = (item: SearchTagItem) => {
    if (this.isSelected(item)) {
      this.props.onSelectionChange(
        this.props.selectedItems.filter((s) => s.id !== item.id)
      );
    } else {
      this.props.onSelectionChange([...this.props.selectedItems, item]);
    }
    this.setSearchInput("");
  };

  clearAll = () => {
    this.props.onSelectionChange([]);
    this.setSearchInput("");
  };

  getTagsHTML = (tags: TagItem[]) => {
    const tagElements = tags.map((tag) => (
      <div key={tag.id} className="badge bg-primary rounded-pill">
        {tag.name}
      </div>
    ));
    return <div className="d-flex flex-wrap gap-1 mt-1">{tagElements}</div>;
  };

  getItemHTML = (item: SearchTagItem) => {
    return (
      <div>
        <div>{item.name}</div>
        {this.getTagsHTML(item.tags)}
      </div>
    );
  };

  getItemsToShow = () => {
    const filteredItems = this.getFilteredItems();
    const itemsToShow = filteredItems.map((item) => {
      const selected = this.isSelected(item);
      return (
        <li
          key={item.id}
          className={`searchselect-item searchselect-item-tags${
            selected ? " searchselect-item-selected" : ""
          }`}
          onMouseDown={(e) => e.preventDefault()}
          onClick={() => this.toggleSelected(item)}
        >
          <div className="d-flex gap-2 align-items-center">
            <span className="searchselect-item-check" aria-hidden="true">
              <i className={`fa ${selected ? "fa-check-square" : "fa-square-o"}`} />
            </span>
            <div className="flex-grow-1">{this.getItemHTML(item)}</div>
          </div>
        </li>
      );
    });
    return itemsToShow;
  };

  render() {
    const { items, searchText, selectedItems } = this.props;
    const itemsToShow = this.getItemsToShow();
    const query = this.state.searchInput.trim();
    const hasQuery = query.length > 0;
    const showResults = this.state.isFocused;
    const hasSelection = selectedItems.length > 0;
    const selectedSummary = hasSelection
      ? selectedItems.map((item) => item.name).join(", ")
      : "";
    const prefix = selectedSummary ? `${selectedSummary}, ` : "";
    const inputValue = this.state.isFocused ? `${prefix}${this.state.searchInput}` : selectedSummary;
    const handleChange = (value: string) => {
      if (prefix && value.startsWith(prefix)) {
        this.setSearchInput(value.slice(prefix.length));
      } else if (prefix) {
        this.setSearchInput("");
      } else {
        this.setSearchInput(value);
      }
    };

    return (
      <div className="searchselect-panel">
        <div className="searchselect-input-wrapper">
          <textarea
            className="form-control searchselect-input-field searchselect-input-field-multi"
            value={inputValue}
            onFocus={() => {
              this.setSearchInput(this.state.searchInput, true);
            }}
            onBlur={() => {
              this.setState({ isFocused: false, searchInput: "" }, this.autoResize);
            }}
            onChange={(e) => handleChange(e.target.value)}
            placeholder={searchText}
            aria-label={this.props.selectText}
            rows={1}
            ref={this.inputRef}
          />
          {(hasQuery || hasSelection) && (
            <div className="searchselect-action-buttons">
              <button
                type="button"
                className="searchselect-action-button"
                aria-label={hasQuery ? "Clear search" : "Clear all"}
                title={hasQuery ? "Clear search" : "Clear all"}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  if (hasQuery) {
                    this.setSearchInput("");
                  } else {
                    this.clearAll();
                  }
                }}
              >
                <i className="fa fa-times" aria-hidden="true"></i>
              </button>
            </div>
          )}
        </div>
        {showResults && (itemsToShow.length > 0 ? (
          <ul className="searchselect-list">{itemsToShow}</ul>
        ) : (
          hasQuery && <div className="text-muted searchselect-empty">No results</div>
        ))}
      </div>
    );
  }
}
